CREATE TABLE vendor_orders (
    id BIGINT PRIMARY KEY,
    user_id BIGINT NOT NULL,
    amount NUMERIC(10, 2)
);

SELECT user_id, SUM(amount) AS total
FROM vendor_orders
GROUP BY user_id;
